const app=document.querySelector('#app'), view=app?.dataset.view;
const pages=[['dashboard','Dashboard','⌂'],['career-guide','Career Guide','✦'],['resume-analyzer','Resume Analyzer','⌁'],['skill-gap','Skill Gap','◎'],['job-match','Job Match','↗'],['projects','Projects','▧'],['interview','Interview Prep','◉'],['progress','Progress','◌'],['applications','Applications','▤'],['profile','Profile & Settings','⚙']];
const guideCopy={'dashboard':'Your career workspace is ready. Choose a tool or continue your next recommended action.','career-guide':'Tell me the role you’re aiming for. I’ll shape a focused roadmap from your saved profile.','resume-analyzer':'Upload your latest resume to begin. Your original file is processed for text and is not stored.','skill-gap':'I’ll compare your saved skills with a role and highlight practical next steps.','job-match':'I’ll use your profile to suggest role directions and legitimate job portals. Suggestions are not live vacancies.','projects':'Build evidence of your skills with a project sized to your current experience.','interview':'Welcome to the practice room. Choose a format and answer one question at a time.','applications':'Keep your job search organized and see your pipeline at a glance.','progress':'Your career journey, in one place. Each completed step reflects saved activity.','profile':'Save your career context once; the platform reuses it across tools.'};
const names={dashboard:['Your career workspace','Turn a clear goal into a practical next move.'], 'career-guide':['Build your 30-day direction','A roadmap should fit your goal, your starting point and your real schedule.'],'resume-analyzer':['Resume intelligence','A transparent, reproducible review of your resume against a target role.'],'skill-gap':['Skill gap studio','See what you already bring, what to strengthen and what to practice next.'],'job-match':['Role & job intelligence','Explore relevant role directions and analyze real job descriptions.'],'projects':['Projects with purpose','Recommendations should help you demonstrate skills honestly.'],'interview':['Practice the interview room','Get deliberate practice for technical, behavioral and HR conversations.'],'applications':['Application tracker','A simple pipeline for the opportunities you’re pursuing.'],'progress':['Your progress, made visible','Your journey reflects what you have actually completed in this workspace.'],'profile':['Your career profile','Keep your career context in one place. You can update it any time.']};
function shell(){const workspacePages=pages.filter(([id])=>id!=='profile');app.innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="side-brand-row"><a class="brand side-brand" href="../index.html">◈ career<span>OS</span></a><a class="side-profile-shortcut ${view==='profile'?'active':''}" href="profile.html" aria-label="Profile & Settings" title="Profile & Settings"><span aria-hidden="true">⚙</span><small>Profile</small></a></div><div class="side-label">WORKSPACE</div><nav class="side-nav">${workspacePages.map(([id,label,icon])=>`<a class="${view===id?'active':''}" href="${id}.html" aria-label="${label}" title="${label}"><span class="nav-icon">${icon}</span>${label}</a>`).join('')}</nav></aside><main class="app-main"><header class="app-top"><div class="app-top-left"><button class="sidebar-toggle" id="menu" type="button" aria-label="Toggle sidebar" title="Toggle sidebar">☰</button><a class="home-top-link" href="dashboard.html"><span aria-hidden="true">⌂</span> Home</a><span class="breadcrumb">Workspace <span class="breadcrumb-separator">/</span> ${pages.find(x=>x[0]===view)?.[1]}</span></div><div class="top-right"><span class="api-state"><i class="status-dot"></i> &nbsp;CAREER ENGINE</span><span class="robot-mini"></span><div class="account-menu"><div class="user-chip account-chip"><span class="avatar" id="avatar">·</span><div><div class="user-name" id="user-name">Career workspace</div><div class="user-sub" id="user-email">Profile</div></div></div><button class="account-signout" id="logout" type="button" aria-label="Sign out" title="Sign out">↪</button></div></div></header><h1 class="page-title">${names[view][0]}</h1><p class="page-intro">${names[view][1]}</p><section class="guide"><span class="guide-bot">◈</span><div><b>YOUR CAREER GUIDE</b><p>${guideCopy[view]}</p></div></section><div id="content"></div></main></div>`;const topControls=app.querySelector('.app-top-left'),persistentNav=document.createElement('div');persistentNav.className='app-persistent-nav';persistentNav.append(...topControls.childNodes);topControls.remove();document.body.append(persistentNav);const shellNode=app.querySelector('.app-shell'),sidebar=app.querySelector('#sidebar'),menu=persistentNav.querySelector('#menu'),mobileQuery=window.matchMedia('(max-width: 680px)');try{if(!mobileQuery.matches&&localStorage.getItem('careeros-sidebar-hidden')==='1')shellNode.classList.add('sidebar-hidden')}catch(_){}const syncMenu=()=>{const open=mobileQuery.matches?sidebar.classList.contains('open'):!shellNode.classList.contains('sidebar-hidden');document.body.classList.toggle('navigation-sidebar-hidden',!mobileQuery.matches&&shellNode.classList.contains('sidebar-hidden'));menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Hide navigation sidebar':'Show navigation sidebar');menu.title=open?'Hide navigation sidebar':'Show navigation sidebar'};syncMenu();menu.onclick=()=>{if(mobileQuery.matches){sidebar.classList.toggle('open')}else{const hidden=shellNode.classList.toggle('sidebar-hidden');try{localStorage.setItem('careeros-sidebar-hidden',hidden?'1':'0')}catch(_){}}syncMenu()};mobileQuery.addEventListener('change',syncMenu);document.querySelector('#logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST'})}finally{location.href='login.html'}}; }
const c=()=>document.querySelector('#content'), formField=(label,name,placeholder='',type='text',value='')=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" placeholder="${placeholder}" value="${escapeHTML(value)}"></div>`, area=(label,name,placeholder='',value='',required=false)=>`<div class="field"><label>${label}</label><textarea name="${name}" placeholder="${placeholder}" ${required?'required':''}>${escapeHTML(value)}</textarea></div>`, button=(text='Generate insight')=>`<button class="button button-primary" type="submit">${text} <span>↗</span></button>`, resultBox=()=>`<div class="result" id="result"></div>`, msg=(t,err=false)=>`<div class="toast ${err?'error':''}">${escapeHTML(t)}</div>`, card=(title,body)=>`<article class="result-card"><h4>${escapeHTML(title.toUpperCase())}</h4>${body}</article>`, list=(items)=>`<ul>${(items||[]).map(x=>`<li>${escapeHTML(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul>`;
function renderResult(node,obj){ node.innerHTML=Object.entries(obj).filter(([k])=>!['text_preview','id'].includes(k)).map(([key,val])=>card(key.replaceAll('_',' '),typeof val==='object'&&val!==null?(Array.isArray(val)?list(val):`<pre class="small muted" style="white-space:pre-wrap">${escapeHTML(JSON.stringify(val,null,2))}</pre>`):`<p>${escapeHTML(val)}</p>`)).join(''); }
async function init(){
 shell(); let user; try{const auth=await api('/auth/me'); user=auth.user; window.careerCsrfToken=auth.csrf_token; document.querySelector('#user-name').textContent=user.name; document.querySelector('#user-email').textContent=user.email; document.querySelector('#avatar').textContent=(user.name||'?')[0].toUpperCase()}catch(_){location.href='login.html';return}
 const content=c();
 if(view==='profile') return profilePage(content);
 if(view==='dashboard') return dashboard(content);
 if(view==='career-guide') return careerPage(content);
 if(view==='skill-gap') return skillPage(content);
 if(view==='resume-analyzer') return resumePage(content);
 if(view==='job-match') return jobsPage(content);
 if(view==='projects') return projectsPage(content);
 if(view==='interview') return interviewPage(content);
 if(view==='applications') return appsPage(content);
 if(view==='progress') return progressPage(content);
}
async function getProfile(){return (await api('/profile')).profile||{}}
async function profilePage(root){const p=await getProfile();root.innerHTML=`<form class="panel" id="profile-form"><h3>Career context</h3><div class="grid grid-2">${formField('Full name','name','Your name','text',p.name||'')}${formField('Target role','target_role','e.g. Data analyst','text',p.target_role||'')}${formField('Experience level','experience','e.g. Early career','text',p.experience||'')}${formField('Available time','available_time','e.g. 1 hour per day','text',p.available_time||'1 hour')}${formField('Education','education','Degree or current study','text',p.education||'')}</div>${area('Current skills (comma separated)','skills','e.g. Python, SQL, communication',(p.skills||[]).join(', '))}${area('Interests','interests','What kind of problems interest you?',p.interests||'')}<div id="form-msg"></div>${button('Save profile')}</form>`;root.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),d=Object.fromEntries(f.entries());d.skills=d.skills.split(',').map(x=>x.trim()).filter(Boolean);try{await api('/profile',{method:'PUT',body:JSON.stringify(d)});root.querySelector('#form-msg').innerHTML=msg('Profile saved. Your career tools will reuse this context.')}catch(err){root.querySelector('#form-msg').innerHTML=msg(err.message,true)}}}
async function dashboard(root){let pr={};let profile={};try{pr=(await api('/progress')).progress}catch(_){}try{profile=await getProfile()}catch(_){}const journey=Array.isArray(pr.journey)?pr.journey:[];const complete=journey.filter(item=>item.complete).length;const total=journey.length;const percent=total?Math.round(complete/total*100):0;const role=profile.target_role||pr.target_role||'';const actionUrl=pr.plan_created?'career-guide.html':role?'career-guide.html':'profile.html';const actionLabel=pr.plan_created?'Continue my roadmap':role?'Build my 30-day roadmap':'Set up my career profile';const focus=pr.plan_created?['Choose one mission from your roadmap','Work through its practice task','Save what you learned']:['Confirm your target role','Add the skills you already use','Generate your first focused roadmap'];const stats=[['Resume signal',pr.latest_ats==null?'—':`${pr.latest_ats}%`,'Latest ATS estimate','resume-analyzer.html'],['Skills',profile.skills?.length||0,'In your career profile','profile.html'],['Applications',pr.applications||0,'In your pipeline','applications.html'],['Milestones',`${complete}/${total}`,'Career journey completed','progress.html']];const toolsList=[['career-guide','✦','Career Guide','Build a focused learning roadmap','01'],['resume-analyzer','⌁','Resume Analyzer','Review your resume signal','02'],['skill-gap','◎','Skill Gap','Find your next priority skill','03'],['job-match','↗','Job Match','Explore roles that fit','04']];root.innerHTML=`<section class="dashboard-control-hero"><div class="dashboard-control-copy"><span class="dashboard-eyebrow">CAREEROS · PERSONAL COMMAND CENTER</span><div class="dashboard-welcome-state"><i></i>${role?'FOCUSED ON YOUR NEXT ROLE':'READY FOR YOUR FIRST STEP'}</div><h2>${pr.plan_created?'Make your next move count.':'Build a direction that fits you.'}</h2><p>${pr.plan_created?`Your ${escapeHTML(role||'career')} roadmap is ready. Choose one practical mission and keep your momentum.`:'Bring your goals and skills together to get a plan built around your next role.'}</p><div class="dashboard-control-actions"><a class="dashboard-main-action" href="${actionUrl}"><span>${actionLabel}</span><i>↗</i></a><a class="dashboard-secondary-action" href="profile.html">Update my profile</a></div><div class="dashboard-role-context"><span>YOUR CURRENT FOCUS</span><b>${escapeHTML(role||'No target role saved yet')}</b><small>${pr.plan_created?'30-day roadmap is active':'Set a role to personalize your workspace'}</small></div></div><div class="dashboard-momentum-visual" aria-label="${percent}% of career milestones completed"><div class="dashboard-momentum-glow"></div><div class="dashboard-momentum-ring ring-outer"></div><div class="dashboard-momentum-ring ring-inner"></div><div class="dashboard-momentum-core"><span>CAREER</span><b>${percent}<small>%</small></b><i>${complete} OF ${total} MILESTONES</i></div><span class="dashboard-momentum-node momentum-profile"><i>01</i> PROFILE</span><span class="dashboard-momentum-node momentum-skill"><i>02</i> SKILLS</span><span class="dashboard-momentum-node momentum-plan"><i>03</i> PLAN</span><span class="dashboard-momentum-node momentum-apply"><i>04</i> APPLY</span><b class="dashboard-momentum-satellite"></b></div></section><section class="dashboard-signal-row">${stats.map(([label,value,detail,href],index)=>`<a class="dashboard-signal-card" href="${href}"><div><span>0${index+1} · ${label.toUpperCase()}</span><b>${escapeHTML(value)}</b></div><small>${detail}</small><i aria-hidden="true"></i></a>`).join('')}</section><section class="dashboard-work-grid"><article class="dashboard-focus-panel"><header><div><span>YOUR NEXT MOVE</span><h3>${pr.plan_created?'One focused mission is enough.':'Start with a strong foundation.'}</h3></div><b>${pr.plan_created?'ROADMAP LIVE':'PROFILE FIRST'}</b></header><p>${pr.plan_created?'A short, practical sequence keeps your plan moving without losing sight of the goal.':'Complete these setup steps and your recommendations will use your own career context.'}</p><div class="dashboard-focus-list">${focus.map((item,index)=>`<div><i>${String(index+1).padStart(2,'0')}</i><span>${item}</span><b>${index===0?'START HERE':'NEXT'}</b></div>`).join('')}</div><a class="dashboard-focus-link" href="${actionUrl}">${actionLabel}<span>↗</span></a></article><section class="dashboard-tools-panel"><header><div><span>YOUR CAREER TOOLKIT</span><h3>Choose a direction</h3></div><small>FOUR WAYS FORWARD</small></header><div class="dashboard-tools-grid">${toolsList.map(([href,icon,title,description,index])=>`<a class="dashboard-tool-tile" href="${href}.html"><div><i>${icon}</i><small>${index}</small></div><b>${title}</b><p>${description}</p><span>Open tool <i>↗</i></span></a>`).join('')}</div></section></section><section class="dashboard-guide-panel"><div class="dashboard-guide-heading"><span>ASK CAREEROS</span><h3>Need help choosing what comes next?</h3><p>Ask a question about your role, roadmap or career priorities.</p></div><form id="assistant-form"><div class="field"><label>Your question</label><input name="message" placeholder="What should I focus on next?" required maxlength="1500"></div><button class="button button-primary">Ask career guide ↗</button></form><div id="assistant-result"></div></section>`;root.querySelector('#assistant-form').onsubmit=async event=>{event.preventDefault();const box=root.querySelector('#assistant-result');box.innerHTML=msg('Thinking through your career context…');try{const data=Object.fromEntries(new FormData(event.currentTarget));const response=(await api('/assistant/message',{method:'POST',body:JSON.stringify({...data,page:'dashboard'})})).result;box.innerHTML=card(response.finding||'Career guidance',`<p><b>Why it matters:</b> ${escapeHTML(response.why_it_matters||'')}</p><p><b>Recommended action:</b> ${escapeHTML(response.recommended_action||'')}</p><p><b>Next step:</b> ${escapeHTML(response.next_step||'')}</p>`)}catch(error){box.innerHTML=msg(error.message,true)}}}async function careerPage(root) {
  const profile = await getProfile();
  root.innerHTML = `<form class="panel career-form-panel" id="career-form"><header class="form-intro"><span>GUIDED SETUP · CAREER ROADMAP</span><h3>Shape your plan</h3><p>Give your guide a starting point and it will shape a focused route.</p></header><div class="grid grid-2">${formField('Target role','target_role','Target role','text',profile.target_role||'')}${formField('Experience level','experience','e.g. early career','text',profile.experience||'')}${formField('Available time','available_time','e.g. 1 hour daily','text',profile.available_time||'1 hour')}</div>${area('Current skills','skills','Python, communication, SQL')}${button('Create 30-day plan')}</form>${resultBox()}`;
  const result = document.querySelector('#result');
  const renderPlan = plan => {
    const days = Array.isArray(plan.plan) ? plan.plan : [];
    const lessonLink = day => {
      const search = encodeURIComponent(`${day.topic || 'career skill'} ${plan.target_role || profile.target_role || ''} tutorial`);
      return `<a class="mission-video-link" href="https://www.youtube.com/results?search_query=${search}" target="_blank" rel="noopener noreferrer" aria-label="Find YouTube lessons for ${escapeHTML(day.topic || 'this mission')}">Find a YouTube lesson ↗</a>`;
    };
    const minutes = days.reduce((total, day) => total + (Number(day.estimated_minutes) || 0), 0);
    const hoursLabel = minutes ? `${Math.floor(minutes / 60)}h ${minutes % 60 ? `${minutes % 60}m` : ''}`.trim() : 'Flexible';
    const missions = Array.from({ length: Math.ceil(days.length / 7) }, (_, week) => {
      const weekDays = days.slice(week * 7, week * 7 + 7);
      const firstDay = String(week * 7 + 1).padStart(2, '0');
      const lastDay = String(week * 7 + weekDays.length).padStart(2, '0');
      return `<section class="mission-week"><header class="mission-week-head"><span>FIELD NOTES · WEEK ${String(week + 1).padStart(2, '0')}</span><span>DAYS ${firstDay}—${lastDay}</span></header><div class="mission-list">${weekDays.map(day => `<article class="mission-card"><div class="mission-index"><span>DAY</span><b>${String(day.day).padStart(2, '0')}</b></div><div class="mission-copy"><span class="mission-kicker">YOUR DAILY MISSION</span><h4>${escapeHTML(day.topic || 'Focused practice')}</h4><p>${escapeHTML(day.practice || day.objective || '')}</p>${day.why ? `<small>WHY THIS MATTERS · ${escapeHTML(day.why)}</small>` : ''}${lessonLink(day)}</div><div class="mission-duration">${Number(day.estimated_minutes) || 60}<span>MIN</span></div></article>`).join('')}</div></section>`;
    }).join('');
    result.innerHTML = `<section class="roadmap-brief"><div class="brief-copy"><span class="brief-label">CAREEROS GUIDE · PERSONAL BRIEFING</span><h2>Your next chapter, mapped.</h2><p class="brief-voice">“I’ve mapped a route toward ${escapeHTML(plan.target_role || profile.target_role || 'your career goal')} around the starting point you shared. Take it one focused mission at a time; I’ll keep your next step in view.”</p><p class="brief-next"><b>My first recommendation</b><span>${escapeHTML(plan.next_action || 'Begin with the first mission below.')}</span></p></div><div class="career-route-art" role="img" aria-label="Animated three-dimensional career path from your starting point to your goal"><span class="route-art-label">YOUR CAREER TRAJECTORY</span><svg class="route-art-path" viewBox="0 0 340 220" aria-hidden="true"><path d="M35 178 C76 160 87 130 127 126 S176 115 197 86 S251 80 300 37"/><circle r="5"><animateMotion dur="6s" repeatCount="indefinite" path="M35 178 C76 160 87 130 127 126 S176 115 197 86 S251 80 300 37"/></circle></svg><div class="route-platform platform-one"><span>01 · START</span><b>Your skills</b></div><div class="route-platform platform-two"><span>02 · BUILD</span><b>New strengths</b></div><div class="route-platform platform-three"><span>03 · GOAL</span><b>${escapeHTML(plan.target_role || profile.target_role || 'Your next role')}</b></div><div class="route-art-orbit"></div><span class="route-art-star">✦</span><span class="route-art-caption">One focused step at a time</span></div></section><div class="roadmap-stats"><article><span>GUIDED MISSIONS</span><b>${days.length}</b></article><article><span>ESTIMATED FOCUS TIME</span><b>${escapeHTML(hoursLabel)}</b></article><article><span>PRIORITY SKILLS</span><b>${(plan.skill_gaps || []).length}</b></article></div><article class="direction-card"><span class="direction-label">THE DIRECTION</span><p>${escapeHTML(plan.summary || '')}</p>${(plan.skill_gaps || []).length ? `<div class="priority-skills"><span>SKILLS TO BUILD</span><div class="chips">${plan.skill_gaps.map(skill => `<span class="chip warn">${escapeHTML(skill)}</span>`).join('')}</div></div>` : ''}</article><div class="mission-heading"><span>YOUR 30-DAY ROUTE</span><p>One focused mission at a time. Your plan is saved to your workspace.</p></div>${missions}`;
  };
  root.querySelector('#career-form').onsubmit = async event => {
    event.preventDefault();
    const submitButton = event.currentTarget.querySelector('button');
    submitButton.disabled = true;
    submitButton.textContent = 'Mapping your next chapter…';
    const details = Object.fromEntries(new FormData(event.currentTarget));
    details.skills = details.skills.split(',').map(skill => skill.trim()).filter(Boolean);
    result.innerHTML = msg(`I’m shaping a 30-day route toward ${details.target_role}. Give me a moment to map your steps.`);
    try {
      const response = await api('/career/plan', { method: 'POST', body: JSON.stringify(details), timeoutMs: 120000 });
      renderPlan(response.plan);
    } catch (error) {
      result.innerHTML = msg(error.message, true);
    } finally {
      submitButton.disabled = false;
      submitButton.textContent = 'Create 30-day plan ↗';
    }
  };
  try {
    const saved = await api('/career/plan');
    if (saved.plan) renderPlan(saved.plan);
  } catch (_) {}
}
async function skillPage(root){const p=await getProfile();const currentSkills=Array.isArray(p.skills)?p.skills.join(', '):(typeof p.skills==='string'?p.skills:'');root.innerHTML=`<section class="skill-hero"><div class="skill-hero-copy"><span class="skill-eyebrow">CAREEROS · SKILL CONSTELLATION</span><h2>See the strengths that move you forward.</h2><p>Choose a destination role and map what you already know against the skills it calls for.</p><span class="skill-hero-note">A practical comparison, shaped around your goal.</span></div><div class="skill-map-visual" role="img" aria-label="A structured skill map showing how strengths and learning priorities connect to a target role"><svg class="skill-map-connectors" viewBox="0 0 320 220" aria-hidden="true"><path d="M26 39 C73 39 65 84 96 94"/><path d="M294 87 C251 87 249 101 224 108"/><path d="M86 201 C106 176 115 165 135 156"/></svg><div class="skill-map-card"><header><span>CAREEROS / CAPABILITY MAP</span><b>PROFILE 01</b></header><div class="skill-map-main"><div class="skill-map-emblem" aria-hidden="true"><svg viewBox="0 0 48 48"><path d="M24 3 42 13.5v21L24 45 6 34.5v-21L24 3Z"/><path d="m24 12 10 6v12l-10 6-10-6V18l10-6Z"/><path d="M24 12v24m10-18-20 12m0-12 20 12"/></svg></div><div><small>SKILL PROFILE</small><strong>Strengths into<br>role fit</strong></div></div><div class="skill-map-track"><i class="done"></i><i class="active"></i><i></i><span></span></div><footer><span>STRENGTHS</span><span>GROWTH</span><span>ROLE FIT</span></footer></div><span class="skill-map-node map-strength"><i>01</i> Strengths</span><span class="skill-map-node map-growth"><i>02</i> Growth</span><span class="skill-map-node map-role"><i>03</i> Role fit</span></div></section><form class="panel skill-form-panel" id="skills-form"><header class="form-intro"><span>BUILD YOUR MAP</span><h3>Where do you want to go next?</h3><p>Your current skills help us find the most useful next steps.</p></header><div class="grid grid-2">${formField('Target role','target_role','e.g. Backend developer','text',p.target_role||'')}${area('Current skills','skills','Add skills, separated by commas',currentSkills,true)}</div><div class="skill-form-action">${button('Analyze skill gap')}</div></form>${resultBox()}`;root.querySelector('form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.skills=d.skills.split(',').map(x=>x.trim()).filter(Boolean);const buttonEl=e.currentTarget.querySelector('button');buttonEl.disabled=true;buttonEl.textContent='Mapping your skills…';try{const out=await api('/skills/analyze',{method:'POST',body:JSON.stringify(d),timeoutMs:120000});const r=out.result;const strongSkills=Array.isArray(r.strong_skills)?r.strong_skills:[];const missingSkills=Array.isArray(r.missing_skills)?r.missing_skills:[];const actionPlan=(Array.isArray(r.action_plan)?r.action_plan:[]).map((item,index)=>{if(typeof item==='string')return item;const skill=item?.skill||item?.topic||item?.name||missingSkills[index]||'Next step';const action=item?.action||item?.recommendation||item?.description||item?.task||'Practice this skill with a small project.';return `${skill}: ${action}`});const before=Math.max(0,Math.min(100,Number(r.simulation.readiness_before)||0));const after=Math.max(0,Math.min(100,Number(r.simulation.readiness_after)||0));const offset=(2*Math.PI*48)*(1-after/100);document.querySelector('#result').innerHTML=`<section class="skill-result-hero"><div><span class="skill-eyebrow">YOUR ROLE READINESS SNAPSHOT</span><h2>A clearer view of your next step.</h2><p>${escapeHTML(r.comparison_basis||'A comparison of your current strengths with your target role.')}</p><div class="skill-readiness-shift"><span>NOW <b>${before}%</b></span><i aria-hidden="true">→</i><span>AFTER ONE PRIORITY SKILL <b>${after}%</b></span></div></div><div class="skill-readiness-ring" role="img" aria-label="Illustrative readiness estimate after learning ${escapeHTML(r.simulation.skill)}: ${after} percent"><svg viewBox="0 0 124 124" aria-hidden="true"><circle class="readiness-track" cx="62" cy="62" r="48"></circle><circle class="readiness-progress" cx="62" cy="62" r="48" style="stroke-dashoffset:${offset}px"></circle></svg><div><strong>${after}</strong><span>ILLUSTRATIVE</span></div></div></section><div class="skill-result-grid">${card('Strong skills',`<div class="chips">${strongSkills.map(x=>`<span class="chip success">${escapeHTML(x)}</span>`).join('')||'No matching strengths yet'}</div>`)}${card('Priority gaps',`<div class="chips">${missingSkills.map(x=>`<span class="chip warn">${escapeHTML(x)}</span>`).join('')||'No missing skills from this comparison'}</div>`)}</div>${card('Action plan',list(actionPlan))}${card('If you learn this',`<p><b>${escapeHTML(r.simulation.skill)}</b> is the example skill used in this illustrative readiness estimate.</p><p>Possible role directions: ${escapeHTML((r.simulation.unlocked_roles||[]).join(', ')||'No adjacent directions suggested')}</p><p class="small">${escapeHTML(r.disclaimer)}</p>`)}${r.ai_status?msg(r.ai_status):''}` }catch(err){document.querySelector('#result').innerHTML=msg(err.message,true)}finally{buttonEl.disabled=false;buttonEl.textContent='Analyze skill gap ↗'}}}
async function resumePage(root){const p=await getProfile();root.innerHTML=`<form class="panel resume-form-panel" id="resume-form"><header class="form-intro"><span>DOCUMENT INTELLIGENCE</span><h3>Make your experience easier to see.</h3><p>Upload your resume and choose the role you are targeting.</p></header><div class="grid grid-2"><div class="field"><label>Resume file · PDF, DOCX or TXT · max 5 MB</label><input name="file" type="file" accept=".pdf,.docx,.txt" required></div>${formField('Target role','target_role','e.g. Product designer','text',p.target_role||'')}</div><p class="small muted">Your uploaded file is processed in memory for analysis and is not retained.</p><div id="form-msg"></div>${button('Analyze resume')}</form><div id="result"></div><div class="spacer"></div><section class="panel"><h3>Resume evolution</h3><div id="history" class="muted small">Loading saved analysis scores…</div></section>`;const renderResult=r=>{if(!r?.ats||!r?.analysis)return;const score=Math.max(0,Math.min(100,Number(r.ats.score)||0));const offset=(2*Math.PI*54)*(1-score/100);const scoreLabel=score>=85?'Strong signal':score>=70?'Good foundation':score>=50?'Room to grow':'Needs attention';document.querySelector('#result').innerHTML=`<section class="resume-result-hero"><div class="resume-scoreboard"><div class="resume-score-copy"><span class="resume-eyebrow">RESUME SIGNAL</span><h2>Your experience, in focus.</h2><p>A clear snapshot of how your resume reads for your target role.</p><span class="resume-score-label">${scoreLabel}</span></div><div class="resume-score-ring" role="img" aria-label="ATS estimate ${score} out of 100"><svg viewBox="0 0 140 140" aria-hidden="true"><circle class="score-track" cx="70" cy="70" r="54"></circle><circle class="score-progress" cx="70" cy="70" r="54" style="stroke-dashoffset:${offset}px"></circle></svg><div class="score-ring-value"><strong>${score}</strong><span>OUT OF 100</span></div></div><p class="resume-score-note">${escapeHTML(r.ats.disclaimer||'A useful estimate based on resume content.')}</p></div><div class="resume-art-panel" aria-label="Animated three-dimensional resume illustration"><div class="resume-art-caption"><span>CAREER PROFILE</span><b>YOUR STORY, WELL PRESENTED</b></div><div class="resume-art-scene"><div class="resume-art-orbit orbit-one"></div><div class="resume-art-orbit orbit-two"></div><div class="resume-art-platform"></div><div class="resume-art-paper paper-back"></div><div class="resume-art-paper paper-front"><i class="paper-avatar"></i><i class="paper-line line-wide"></i><i class="paper-line line-short"></i><i class="paper-section"></i><i class="paper-line"></i><i class="paper-line line-mid"></i><i class="paper-section second"></i><i class="paper-line"></i><i class="paper-line line-short"></i><span class="paper-seal">✦</span></div><span class="resume-art-node node-one">✦</span><span class="resume-art-node node-two">✓</span></div><p class="resume-art-foot">A stronger story starts with the details.</p></div></section><section class="resume-breakdown"><header><span class="resume-eyebrow">SIGNAL BREAKDOWN</span><p>Explore the parts that shape your overall estimate.</p></header><div class="resume-metric-grid">${Object.entries(r.ats.breakdown||{}).map(([k,v])=>`<article class="resume-metric"><span>${escapeHTML(k.replaceAll('_',' ').toUpperCase())}</span><strong>${v}<small>%</small></strong><div class="progress-bar"><i style="width:${v}%"></i></div></article>`).join('')}</div></section><div class="resume-feedback-grid">${card('Analysis',`<p>${escapeHTML(r.analysis.summary||'')}</p>`)}${card('Strengths',list(r.analysis.strengths))}${card('Skills / keywords to consider',list(r.analysis.missing_skills))}${card('Actionable improvements',list(r.analysis.improvements))}</div>${r.analysis.ai_status?msg(r.analysis.ai_status):''}`};root.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;b.textContent='Analyzing your resume…';try{const fd=new FormData(e.currentTarget);const out=await api('/resume/analyze',{method:'POST',body:fd,timeoutMs:120000});renderResult(out.result);await loadResumeHistory()}catch(err){document.querySelector('#form-msg').innerHTML=msg(err.message,true)}finally{b.disabled=false;b.textContent='Analyze resume ↗'}};const items=await loadResumeHistory();if(items?.length)renderResult(items[items.length-1])}
async function loadResumeHistory(){try{const items=(await api('/resume/history')).items;document.querySelector('#history').innerHTML=items.length?items.map((x,i)=>`<span class="chip">Version ${i+1} · ${x.ats.score}/100 · ${new Date(x.created_at).toLocaleDateString()}</span>`).join(' '):'No resume analyses yet.';return items}catch(_){return []}}
async function jobsPage(root){root.innerHTML=`<section class="job-match-hero"><div class="job-match-copy"><span class="job-match-eyebrow">CAREEROS · ROLE INTELLIGENCE</span><h2>Find the work that fits your strengths.</h2><p>Explore role directions from your profile or compare your skills with a job description you care about.</p><span class="job-match-note">Clear signals for your next application.</span></div><div class="job-radar-art" role="img" aria-label="Animated role matching radar connecting your profile with opportunities"><div class="job-radar-ring ring-a"></div><div class="job-radar-ring ring-b"></div><div class="job-radar-ring ring-c"></div><div class="job-radar-sweep"></div><div class="job-radar-core" role="img" aria-label="Three-dimensional career portfolio with a role match check"><div class="job-portfolio"><i class="portfolio-handle"></i><span class="portfolio-emblem">✓</span><i class="portfolio-shine"></i></div><span class="portfolio-label">PROFILE FIT</span></div><span class="job-radar-point point-a">SKILLS</span><span class="job-radar-point point-b">ROLE</span><span class="job-radar-point point-c">FIT</span><span class="job-radar-star">✦</span></div></section><div class="job-workbench"><section class="panel role-directions-panel"><header class="form-intro"><span>ROLE DIRECTIONS</span><h3>Explore paths from your profile</h3><p>Search suggestions use the target role and skills from your saved profile and latest resume analysis.</p></header><div class="role-route-visual" aria-label="A visual route from your profile through role matching to job opportunities"><div class="route-visual-head"><span class="route-spark">✦</span><div><small>YOUR CAREER ROUTE</small><b>From your profile to your next role</b></div><span class="route-live">READY</span></div><div class="route-track"><div class="route-stop"><i>01</i><b>Your profile</b><span>Skills & goals</span></div><span class="route-connector"></span><div class="route-stop route-stop-active"><i>02</i><b>Role match</b><span>Target direction</span></div><span class="route-connector"></span><div class="route-stop"><i>03</i><b>Open roles</b><span>Trusted portals</span></div></div></div><button class="button button-primary" id="match">Explore role direction</button><div id="matches" class="result"><section class="role-search-guide"><div class="role-guide-heading"><span class="role-guide-icon">⌕</span><div><small>YOUR SEARCH, MADE USEFUL</small><h4>Find roles worth your time</h4></div></div><p>We’ll turn your saved role and skills into a starting search across job platforms.</p><div class="role-guide-steps"><article><i>01</i><div><b>Compare the role</b><span>Check the responsibilities, experience level and location.</span></div></article><article><i>02</i><div><b>Look for your strengths</b><span>Use your skills to spot listings that fit what you can already do.</span></div></article><article><i>03</i><div><b>Apply on the job site</b><span>Open a listing, review the employer, then follow its application steps.</span></div></article></div><div class="role-guide-footer"><span>✦</span>Click <b>Explore role direction</b> to load your role-specific job search links.</div></section></div></section><form class="panel job-analyzer-panel" id="jd-form"><header class="form-intro"><span>JOB DESCRIPTION ANALYZER</span><h3>Check a role that interests you</h3><p>Paste the description to see matched skills, gaps, keywords and interview topics.</p></header>${area('Job description','description','Paste responsibilities and requirements here…','',true)}<div class="job-analyzer-actions">${button('Analyze this role')}</div><div class="jd-insight-panel"><div class="jd-scan-art" aria-hidden="true"><div class="jd-scan-orbit orbit-one"></div><div class="jd-scan-orbit orbit-two"></div><div class="jd-scan-sheet"><i class="scan-avatar"></i><i class="scan-line scan-line-long"></i><i class="scan-line"></i><i class="scan-line scan-line-short"></i><i class="scan-section"></i><i class="scan-line"></i><i class="scan-line scan-line-long"></i><span class="scan-check">✓</span></div><span class="scan-light"></span><span class="scan-caption">SIGNAL SCAN</span></div><div class="jd-insight-copy"><span>WHAT YOU’LL GET</span><b>A clearer read on the role</b><p>Your description is compared with your saved profile to surface:</p><div class="jd-signal-list"><i>Matched skills</i><i>Skills to strengthen</i><i>Keywords & interview topics</i></div><small>Paste the full role description above for the most useful comparison.</small></div></div><section id="job-after-search" class="job-after-search" hidden><header><span>APPLICATION WORKFLOW</span><b>Turn a role match into a strong application</b><p id="job-application-role">Your next steps for this role</p></header><div class="job-application-steps"><article><i>01</i><div><b>Check the must-haves</b><span>Confirm the location, experience level and essential requirements in the posting.</span></div></article><article><i>02</i><div><b>Connect it to your resume</b><span>Choose real projects or experience that demonstrate the closest matching skills.</span></div></article><article><i>03</i><div><b>Use the analyzer above</b><span>Paste the job description to spot matched skills, gaps and useful interview topics.</span></div></article><article><i>04</i><div><b>Apply on the listing site</b><span>Verify the employer and follow the application instructions on the original listing.</span></div></article></div><div class="job-application-tip"><span>✦</span><p><b>Good applications are specific.</b> Tailor your examples to the role and keep the final version truthful.</p></div></section></form></div><div id="jd-result" class="result job-match-results"></div>`;const matchesBox=root.querySelector('#matches');matchesBox.addEventListener('click',event=>{const edit=event.target.closest('.job-search-edit-button');if(edit){const form=edit.parentElement.parentElement.querySelector('.job-search-edit-form');form.hidden=false;edit.hidden=true;form.querySelector('[name=search_terms]').focus();return}const cancel=event.target.closest('.job-search-cancel-button');if(cancel){const form=cancel.closest('.job-search-edit-form');form.hidden=true;form.parentElement.querySelector('.job-search-edit-button').hidden=false}});matchesBox.addEventListener('submit',async event=>{const form=event.target.closest('.job-search-edit-form');if(!form)return;event.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Updating links…';try{const payload=Object.fromEntries(new FormData(form));const response=await api('/jobs/match',{method:'POST',body:JSON.stringify(payload)});const item=response.matches?.[0];if(!item)throw new Error('No updated job links were returned.');matchesBox.querySelector('.job-search-terms').textContent=item.search_terms;matchesBox.querySelector('.job-search-basis').textContent='Based on '+item.search_basis;for(const link of matchesBox.querySelectorAll('.job-portal-link')){const href=item.portals?.[link.dataset.portal];if(href){link.href=href;link.setAttribute('aria-label','Search '+item.search_terms+' on '+link.dataset.portal)}}form.querySelector('[name=search_terms]').value=item.search_terms;form.hidden=true;form.parentElement.querySelector('.job-search-edit-button').hidden=false;let status=matchesBox.querySelector('.job-search-update-status');if(!status){status=document.createElement('p');status.className='job-search-update-status';form.after(status)}status.textContent='Search links updated. Choose a platform below to browse listings.'}catch(error){let status=matchesBox.querySelector('.job-search-update-status');if(!status){status=document.createElement('p');status.className='job-search-update-status error';form.after(status)}status.textContent=error.message}finally{submit.disabled=false;submit.textContent='Update portal links'}});root.querySelector('#match').onclick=async()=>{const box=document.querySelector('#matches');box.innerHTML=msg('Using your saved profile…');try{const out=await api('/jobs/match',{method:'POST',body:JSON.stringify({})});box.innerHTML=out.matches.map(x=>{const portals=Object.entries(x.portals||{}).map(([n,u])=>'<a class="job-portal-link" data-portal="'+escapeHTML(n)+'" target="_blank" rel="noopener noreferrer" aria-label="Search '+escapeHTML(x.search_terms||x.role)+' on '+escapeHTML(n)+'" href="'+escapeHTML(u)+'"><b>'+escapeHTML(n)+'</b><span>Browse matching listings ↗</span></a>').join('');const learning=(x.learning_resources||[]).map(item=>'<a class="job-learning-link" target="_blank" rel="noopener noreferrer" href="'+escapeHTML(item.url)+'"><b>'+escapeHTML(item.name)+'</b><span>'+escapeHTML(item.description)+'</span></a>').join('');return card(x.role,'<div class="role-results-intro"><span>YOUR ROLE SEARCH IS READY</span><b>Choose a platform to browse matching listings</b></div><p>'+escapeHTML(x.why_it_matches)+'</p><div class="job-search-heading"><p class="job-portal-label"><b>SEARCHING FOR</b></p><button type="button" class="job-search-edit-button">Edit</button></div><p class="job-search-terms">'+escapeHTML(x.search_terms||x.role)+'</p><p class="job-search-basis">Based on '+escapeHTML(x.search_basis||'your saved profile')+'</p><form class="job-search-edit-form" hidden><input type="hidden" name="target_role" value="'+escapeHTML(x.role)+'"><label>Edit search phrase<input type="search" name="search_terms" maxlength="300" required value="'+escapeHTML(x.search_terms||x.role)+'"></label><div><button type="submit" class="button button-primary">Update portal links</button><button type="button" class="job-search-cancel-button">Cancel</button></div></form><p class="job-portal-label"><b>JOB SEARCH PLATFORMS</b></p><div class="job-portal-links">'+portals+'</div><p class="job-portal-safety">Check each listing and employer before applying. Never pay a recruiter to get a job.</p><div class="job-learning-resources"><span>LEARN OR STRENGTHEN SKILLS</span>'+learning+'</div>')}).join('');const checklist=document.querySelector('#job-after-search');checklist.hidden=false;document.querySelector('#job-application-role').textContent='A practical checklist for '+out.matches[0].role+'.';box.scrollIntoView({behavior:'smooth',block:'nearest'})}catch(e){box.innerHTML=msg(e.message,true)}};root.querySelector('#jd-form').onsubmit=async e=>{e.preventDefault();const box=document.querySelector('#jd-result');box.innerHTML=msg('Comparing role requirements with your profile…');try{const d=Object.fromEntries(new FormData(e.currentTarget));const r=(await api('/jobs/analyze-description',{method:'POST',body:JSON.stringify(d)})).result;const score=Math.max(0,Math.min(100,Number(r.match)||0));const offset=(2*Math.PI*48)*(1-score/100);box.innerHTML=`<section class="job-analysis-hero"><div><span class="job-match-eyebrow">ROLE FIT SNAPSHOT</span><h2>Your profile against this opportunity.</h2><p>${escapeHTML(r.disclaimer||'A skills overlap estimate based on the job description and your saved profile.')}</p></div><div class="job-fit-ring" role="img" aria-label="Profile overlap estimate ${score} percent"><svg viewBox="0 0 124 124" aria-hidden="true"><circle class="job-fit-track" cx="62" cy="62" r="48"></circle><circle class="job-fit-progress" cx="62" cy="62" r="48" style="stroke-dashoffset:${offset}px"></circle></svg><div><strong>${score}</strong><span>PROFILE FIT</span></div></div></section><div class="job-analysis-grid">${card('Matched skills',list(r.matched_skills))}${card('Skills to review',list(r.missing_skills))}${card('Important keywords',`<div class="chips">${(r.important_keywords||[]).map(x=>`<span class="chip">${escapeHTML(x)}</span>`).join('')||'<span class="muted">No standout keywords found.</span>'}</div>`)}${card('Interview prep topics',list(r.interview_topics))}</div>`}catch(err){box.innerHTML=msg(err.message,true)}}}
async function projectsPage(root){
 let context;
 try{context=(await api('/projects/context')).context}catch(error){root.innerHTML=msg(error.message,true);return}
 const esc=escapeHTML;
 const skillChips=()=>context.skills.length?context.skills.map(skill=>'<span class="project-context-chip">'+esc(skill)+'</span>').join(''):'<span class="project-context-empty">No resume/profile skills found yet. Add a few with Edit inputs.</span>';
 root.innerHTML='<section class="project-lab-hero"><div class="project-lab-copy"><span>CAREEROS · PROJECT LAB</span><h2>Build proof of what you can do.</h2><p>Turn the role and skills in your resume into a focused portfolio project you can actually complete.</p><div class="project-lab-note"><i>✦</i> Every idea is a learning plan, never a claim that you have already done the work.</div><button class="button button-primary project-hero-action" id="recommend">Recommend a project ↗</button></div><div class="project-lab-art" aria-hidden="true"><div class="project-blueprint-back"></div><div class="project-build-card"><header><span class="build-card-mark">✦</span><small>PROJECT BRIEF</small><i>01</i></header><b>Role-fit build</b><p>Skills → working product</p><div class="build-card-progress"><i></i></div><div class="build-card-tags"><span>PLAN</span><span>BUILD</span><span>SHOWCASE</span></div><span class="build-card-seal">✓</span></div><div class="project-stage-line"><span><i>01</i> PLAN</span><b></b><span><i>02</i> BUILD</span><b></b><span><i>03</i> SHOWCASE</span></div></div></section><section class="panel project-context-panel"><div class="project-context-heading"><div><span>RECOMMENDATION INPUTS</span><h3>What the project ideas will use</h3><p>Based on your saved career information. Edit these details before generating ideas.</p></div><button type="button" class="project-edit-button" id="project-edit">Edit inputs</button></div><div class="project-context-grid"><article><small>TARGET ROLE</small><b id="project-role-view">'+esc(context.target_role||'Add your target role')+'</b><span id="project-role-source">'+esc(context.role_source)+'</span></article><article><small>EXPERIENCE</small><b id="project-experience-view">'+esc(context.experience||'Not specified')+'</b><span>Saved profile</span></article><article class="project-skills-context"><small>SKILLS USED</small><div id="project-skills-view">'+skillChips()+'</div><span id="project-skills-source">'+esc(context.skills_source)+(context.resume_filename?' · '+esc(context.resume_filename):'')+'</span></article></div><form id="project-edit-form" class="project-edit-form" hidden><label>Target role<input name="target_role" maxlength="120" value="'+esc(context.target_role||'')+'" placeholder="e.g. Software developer"></label><label>Skills from your profile/resume, separated by commas<textarea name="skills" rows="3" maxlength="700">'+esc(context.skills.join(', '))+'</textarea></label><label>Experience level<input name="experience" maxlength="80" value="'+esc(context.experience||'')+'" placeholder="e.g. Final-year student, early career"></label><div><button type="submit" class="button button-primary">Save inputs</button><button type="button" id="project-edit-cancel" class="project-edit-cancel">Cancel</button></div></form><div class="project-context-source"><span>↳</span><p id="project-source-explanation">'+(context.has_resume?'Using your latest analyzed resume'+(context.resume_filename?' ('+esc(context.resume_filename)+')':'')+' for its target role and detected skills, combined with skills saved in your profile.':'No analyzed resume found yet. Using your saved profile; upload and analyze a resume to include its role and detected skills.')+'</p></div></section><section class="panel project-recommend-panel"><div class="project-recommend-copy"><span>IDEA GENERATOR</span><h3>Make your next skill visible.</h3><p>Get a practical project brief, build sequence and a truthful resume-bullet starter based on the inputs above.</p></div><div id="result" class="result"></div></section>';
 const editForm=root.querySelector('#project-edit-form');const fillEditForm=()=>{editForm.elements.target_role.value=context.target_role||'';editForm.elements.skills.value=context.skills.join(', ');editForm.elements.experience.value=context.experience||''};
 root.querySelector('#project-edit').onclick=()=>{fillEditForm();editForm.hidden=false;editForm.elements.target_role.focus()};
 root.querySelector('#project-edit-cancel').onclick=()=>{editForm.hidden=true};
 editForm.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(editForm));context={...context,target_role:values.target_role.trim(),skills:values.skills.split(',').map(v=>v.trim()).filter(Boolean),experience:values.experience.trim(),role_source:'Edited by you',skills_source:'Edited by you'};root.querySelector('#project-role-view').textContent=context.target_role||'Add your target role';root.querySelector('#project-role-source').textContent=context.role_source;root.querySelector('#project-experience-view').textContent=context.experience||'Not specified';root.querySelector('#project-skills-view').innerHTML=skillChips();root.querySelector('#project-skills-source').textContent=context.skills_source;root.querySelector('#project-source-explanation').textContent='These are your edited recommendation inputs. They will be used for this project request and will not change your saved profile.';editForm.hidden=true};
 const renderProject=(x,index)=>{const skills=(Array.isArray(x.skills)?x.skills:[]).map(skill=>'<span class="project-result-skill">'+esc(skill)+'</span>').join('');const features=(Array.isArray(x.features)?x.features:[]).map((item,i)=>'<li><i>✓</i>'+esc(item)+'</li>').join('');const roadmap=(Array.isArray(x.roadmap)?x.roadmap:[]).map((item,i)=>'<li><i>'+String(i+1).padStart(2,'0')+'</i><span>'+esc(item)+'</span></li>').join('');const bullets=(Array.isArray(x.resume_bullets)?x.resume_bullets:[]).map(item=>'<li>'+esc(item)+'</li>').join('');return '<article class="project-blueprint"><header class="project-blueprint-head"><div class="project-index">'+String(index+1).padStart(2,'0')+'</div><div><span>PORTFOLIO BLUEPRINT</span><h3>'+esc(x.title||'Project idea')+'</h3></div><span class="project-difficulty">'+esc(x.difficulty||'Flexible')+'</span></header><p class="project-blueprint-description">'+esc(x.description||'A project idea tailored to your selected role and skills.')+'</p><div class="project-result-skills"><small>SKILLS YOU’LL PRACTICE</small><div>'+skills+'</div></div><div class="project-blueprint-grid"><section><span>FEATURE TARGETS</span><ul class="project-feature-list">'+features+'</ul></section><section><span>BUILD SEQUENCE</span><ol class="project-roadmap-list">'+roadmap+'</ol></section></div><section class="project-resume-starter"><span>AFTER YOU COMPLETE IT</span><ul>'+bullets+'</ul><small>Edit the wording to reflect what you actually built and measured.</small></section></article>'};
 root.querySelector('#recommend').onclick=async()=>{const button=root.querySelector('#recommend');button.disabled=true;button.textContent='Designing your project blueprint…';const resultBox=root.querySelector('#result');resultBox.innerHTML=msg('Using '+(context.resume_filename||'your saved profile')+' to shape project ideas…');try{const response=await api('/projects/recommend',{method:'POST',body:JSON.stringify({target_role:context.target_role,skills:context.skills,experience:context.experience})});context={...context,...response.context};const projects=Array.isArray(response.result?.projects)?response.result.projects:[];resultBox.innerHTML='<section class="project-result-source"><span>PERSONALIZED FROM YOUR CONTEXT</span><b>'+esc(context.target_role||'Career exploration')+'</b><p>Used: '+esc(context.role_source)+' for the target role; '+esc(context.skills_source)+' for '+esc(context.skills.join(', ')||'no listed skills')+'.</p></section>'+projects.map((project,index)=>renderProject(project,index)).join('')+(response.result?.note?'<p class="project-result-note">'+esc(response.result.note)+'</p>':'');resultBox.scrollIntoView({behavior:'smooth',block:'start'})}catch(error){resultBox.innerHTML=msg(error.message,true)}finally{button.disabled=false;button.textContent='Recommend a project ↗'}}
}
async function interviewPage(root){
 root.innerHTML=`<section class="interview-hero"><div class="interview-hero-copy"><span>CAREEROS · INTERVIEW STUDIO</span><h2>Practice with purpose.</h2><p>Choose the round and level you want to rehearse. Your interviewer will ask questions for that exact format.</p><div class="interview-hero-note"><i>✦</i> One question at a time. Answer naturally, then review practical feedback.</div></div><div class="interview-agent-scene" aria-label="AI interviewer ready for practice"><div class="interview-agent-orbit orbit-a"></div><div class="interview-agent-orbit orbit-b"></div><div class="interview-agent-card"><span>AI INTERVIEWER</span><div class="interview-agent-face"><i></i><i></i><b></b></div><strong>READY</strong></div><span class="interview-agent-node agent-node-a">ROUND</span><span class="interview-agent-node agent-node-b">FEEDBACK</span></div></section><section class="panel interview-setup-panel"><div class="interview-setup-heading"><div><span>ROUND CONFIGURATION</span><h3>Set your practice session</h3><p>Your selected round will be shown beside each question.</p></div><span class="interview-setup-mark">01 / 02</span></div><form id="start-form"><div class="grid grid-3"><div class="field"><label>Interview round</label><select name="type"><option value="mixed">Mixed round</option><option value="technical">Technical round</option><option value="behavioral">Behavioral round</option><option value="HR">HR round</option></select></div><div class="field"><label>Difficulty</label><select name="difficulty"><option value="beginner">Beginner</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option></select></div>${formField('Target role','target_role','Saved role is used if blank')}</div><div class="interview-setup-footer"><div id="round-preview" class="round-preview"><span>YOUR SELECTED ROUND</span><b>Mixed round · Beginner</b><small>Questions will follow this format and level.</small></div>${button('Start practice')}</div></form></section><div id="question" class="result interview-session-result"></div>`;
 const form=root.querySelector('#start-form');const updatePreview=()=>{const type=form.elements.type.value;const difficulty=form.elements.difficulty.value;const pretty=value=>value==='HR'?'HR':value.charAt(0).toUpperCase()+value.slice(1);root.querySelector('#round-preview b').textContent=pretty(type)+' round · '+pretty(difficulty)};form.elements.type.onchange=updatePreview;form.elements.difficulty.onchange=updatePreview;
 form.onsubmit=async event=>{event.preventDefault();const submitButton=form.querySelector('button[type="submit"]')||form.querySelector('button');submitButton.disabled=true;submitButton.textContent='Preparing your round…';try{const data=Object.fromEntries(new FormData(form));const out=await api('/interview/start',{method:'POST',body:JSON.stringify(data)});showQuestion(out.session.question,out)}catch(error){root.querySelector('#question').innerHTML=msg(error.message,true)}finally{submitButton.disabled=false;submitButton.textContent='Start practice ↗'}}
}
function showQuestion(q,meta={}){const box=document.querySelector('#question');const session=meta.session||meta;const round=session.type||'mixed';const difficulty=session.difficulty||'beginner';const role=session.role||'your target role';const pretty=value=>value==='HR'?'HR':String(value).charAt(0).toUpperCase()+String(value).slice(1);const number=meta.questionNumber||1;const criteria=Array.isArray(meta.criteria)?meta.criteria:[];box.innerHTML=`<section class="interview-question-card"><header class="interview-question-header"><div class="interviewer-avatar interviewer-voice" aria-label="AI interviewer speaking"><span>AI</span><div class="voice-bars"><i></i><i></i><i></i><i></i><i></i></div><b></b></div><div class="interviewer-heading"><span>CAREEROS INTERVIEWER · QUESTION ${number}</span><h3>Your practice round</h3><p>Role focus: ${escapeHTML(role)}</p></div><div class="interview-round-badge"><small>SELECTED ROUND</small><b>${escapeHTML(pretty(round))}</b><span>${escapeHTML(pretty(difficulty))} difficulty</span></div></header><div class="interview-question-body"><div class="interview-live-label"><span class="live-dot"></span> THE INTERVIEWER IS ASKING <span class="interview-live-line"></span></div><div class="interview-speech-card"><div class="interview-speech-meta"><span>QUESTION ${String(number).padStart(2,'0')}</span><span>${escapeHTML(pretty(round))} · ${escapeHTML(pretty(difficulty))}</span></div><h2>${escapeHTML(q||'')}</h2><p>Take a moment to think. Answer as if you were in the room.</p></div><div class="interview-flow"><span class="is-current"><i>01</i> Listen</span><b></b><span><i>02</i> Respond</span><b></b><span><i>03</i> Get coaching</span></div>${criteria.length?'<div class="interview-criteria"><span>WHAT TO COVER</span>'+criteria.map(item=>'<i>'+escapeHTML(item)+'</i>').join('')+'</div>':''}<form id="answer-form">${area('Your answer','answer','Explain your thinking clearly. Use a specific example when it helps.') }<div class="interview-answer-footer"><span>Your answer is used to generate practice feedback.</span>${button('Review my answer')}</div></form></div></section>${meta.ai_status?msg(meta.ai_status):''}`;requestAnimationFrame(()=>box.scrollIntoView({behavior:'smooth',block:'start'}));box.querySelector('form').onsubmit=async event=>{event.preventDefault();const answer=new FormData(event.currentTarget).get('answer');const submit=event.currentTarget.querySelector('button[type="submit"]')||event.currentTarget.querySelector('button');submit.disabled=true;submit.textContent='Reviewing your answer…';try{const response=await api('/interview/answer',{method:'POST',body:JSON.stringify({question:q,answer,type:round,difficulty,role})});const result=response.result||{};const strengths=Array.isArray(result.strengths)?result.strengths:[];const next=result.next_question;box.insertAdjacentHTML('beforeend',`<section class="interview-feedback-card"><div class="interview-feedback-heading"><div><span>COACHING NOTES</span><h3>Feedback for this answer</h3></div>${result.score==null?'':`<strong class="interview-score">${escapeHTML(result.score)}<small>/100</small></strong>`}</div><div class="interview-feedback-grid"><div><b>What worked</b>${strengths.length?'<ul>'+strengths.map(item=>'<li>'+escapeHTML(item)+'</li>').join('')+'</ul>':'<p>Keep building clear, specific examples as you practice.</p>'}</div><div><b>Try next</b><p>${escapeHTML(result.improvement||'Add a little more detail about your approach and its result.')}</p></div></div>${result.suggested_structure?`<p class="interview-structure"><b>A useful structure</b><br>${escapeHTML(result.suggested_structure)}</p>`:''}${result.ai_status?msg(result.ai_status):''}${next?'<button class="button button-glass next-question">Practice the next question →</button>':''}</section>`);box.querySelector('.next-question')?.addEventListener('click',()=>showQuestion(next,{session,questionNumber:Number(number)+1}))}catch(error){box.insertAdjacentHTML('beforeend',msg(error.message,true))}finally{if(submit.isConnected){submit.disabled=false;submit.textContent='Review my answer'}}}}
async function appsPage(root){const statuses=['Saved','Applied','Assessment','Interview','Offer','Rejected'];root.innerHTML=`<section class="applications-hero"><div class="applications-hero-copy"><span>CAREEROS · OPPORTUNITY PIPELINE</span><h2>Turn a good lead into your next move.</h2><p>Keep every role, follow-up and interview in one calm, organized place. Update a status as your search moves forward.</p><div class="application-stage-key"><span><i></i>Saved</span><b></b><span><i></i>Applied</span><b></b><span><i></i>Interview</span><b></b><span><i></i>Offer</span></div></div><div class="application-flow-art" aria-label="Application stages from saved to offer"><div class="application-flow-orbit"></div><div class="application-flow-core"><span>YOUR</span><b>CAREER</b><small>PIPELINE</small></div><div class="application-flow-step flow-step-one"><i>01</i><span>Save a role</span></div><div class="application-flow-step flow-step-two"><i>02</i><span>Apply</span></div><div class="application-flow-step flow-step-three"><i>03</i><span>Interview</span></div><div class="application-flow-step flow-step-four"><i>04</i><span>Offer</span></div><div class="application-flow-pulse"></div></div></section><form class="panel application-entry-panel" id="app-form"><header class="application-entry-heading"><div><span>ADD TO YOUR PIPELINE</span><h3>Capture an opportunity</h3><p>Start with the role and company. Add dates or notes whenever useful.</p></div><span class="application-entry-step">NEW ROLE</span></header><div class="application-form-grid">${formField('Company','company','Company name')}${formField('Role','role','Role title')}${formField('Application date','application_date','','date')}<div class="field"><label>Status</label><select name="status">${statuses.map(status=>`<option>${status}</option>`).join('')}</select></div>${formField('Interview date','interview_date','','date')}</div><div class="application-notes-field">${area('Notes','notes','Contact, follow-up date, interview details or next action')}</div><footer class="application-entry-footer"><span>Keep notes factual and add a follow-up date when you can.</span>${button('Add application')}</footer></form><section class="panel application-pipeline-panel"><header><div><span>YOUR SEARCH, ORGANIZED</span><h3>Your pipeline</h3><p>Update each opportunity as it progresses.</p></div></header><div id="table" class="table-wrap"></div></section>`;root.querySelector('#app-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;const submit=form.querySelector('button[type="submit"]')||form.querySelector('button');const data=Object.fromEntries(new FormData(form));submit.disabled=true;submit.textContent='Saving opportunity…';try{await api('/applications',{method:'POST',body:JSON.stringify(data)});form.reset();await loadApps()}catch(error){root.querySelector('#table').innerHTML=msg(error.message,true)}finally{submit.disabled=false;submit.textContent='Add application ↗'}};loadApps()}async function loadApps(){try{const items=(await api('/applications')).items;document.querySelector('#table').innerHTML=items.length?`<table class="data-table"><thead><tr><th>Company / role</th><th>Date</th><th>Status</th><th>Notes</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td><b>${escapeHTML(x.company)}</b><br><span class="muted">${escapeHTML(x.role)}</span></td><td>${escapeHTML(x.application_date)}</td><td><select data-id="${x.id}" class="status-select">${['Saved','Applied','Assessment','Interview','Offer','Rejected'].map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select></td><td>${escapeHTML(x.notes)}</td><td><button class="button delete-app" data-id="${x.id}">Remove</button></td></tr>`).join('')}</tbody></table>`:'<div class="application-empty-state"><span class="application-empty-icon">↗</span><div><b>Your pipeline starts with one opportunity.</b><p>Add a role above to keep its status, interview date and next step together.</p></div><a class="application-empty-cta" href="#app-form">Add your first role <span aria-hidden="true">↗</span></a></div>';document.querySelectorAll('.status-select').forEach(el=>el.onchange=async()=>{await api('/applications/'+el.dataset.id,{method:'PUT',body:JSON.stringify({status:el.value})})});document.querySelectorAll('.delete-app').forEach(el=>el.onclick=async()=>{await api('/applications/'+el.dataset.id,{method:'DELETE'});loadApps()})}catch(err){document.querySelector('#table').innerHTML=msg(err.message,true)}}
async function progressPage(root){root.innerHTML='<div class="muted small">Gathering your saved progress…</div>';try{const p=(await api('/progress')).progress;const journey=Array.isArray(p.journey)?p.journey:[];const complete=journey.filter(item=>item.complete).length;const total=journey.length;const percent=total?Math.round(complete/total*100):0;const next=journey.find(item=>!item.complete);const stats=[['Applications',p.applications,'01','Roles and companies in your tracker.','Open pipeline','applications.html'],['Interviews',p.interviews,'02','Applications currently at interview stage.','View pipeline','applications.html'],['Offers',p.offers,'03','Opportunities marked as an offer.','View pipeline','applications.html'],['Resume analyses',p.resume_analyses,'04','Resume reviews saved to your workspace.','Review resumes','resume-analyzer.html']];root.innerHTML=`<section class="progress-showcase"><div class="progress-showcase-copy"><span>CAREEROS · YOUR MOMENTUM</span><h2>Every step adds up.</h2><p>Your workspace activity, gathered into one clear view. Completed milestones come from what you have actually saved.</p><div class="progress-next-step"><span>NEXT MILESTONE</span><b>${next?escapeHTML(next.stage):'Your journey is complete'}</b><small>${next?'Complete this step to move your career journey forward.':'You have completed every milestone shown here.'}</small></div></div><div class="progress-orb-scene" aria-label="${percent}% of career milestones completed"><div class="progress-orb-ring ring-back"></div><div class="progress-orb-ring ring-front"></div><div class="progress-orb"><span>JOURNEY</span><b>${percent}<small>%</small></b><i>${complete} OF ${total} STEPS</i></div><span class="progress-orb-node orb-node-one">PROFILE</span><span class="progress-orb-node orb-node-two">GROWTH</span><span class="progress-orb-node orb-node-three">NEXT</span></div></section><section class="progress-stat-grid">${stats.map(([label,value,index,detail,action,href])=>`<article class="progress-stat"><div><span>${index} · WORKSPACE</span><b>${escapeHTML(value??0)}</b></div><section class="progress-stat-detail"><small>${label}</small><p>${detail}</p></section><a href="${href}">${action} ↗</a><i aria-hidden="true"></i></article>`).join('')}</section><section class="progress-journey-panel"><header><div><span>YOUR CAREER PATH</span><h3>Milestones in motion</h3><p>${complete} of ${total} milestones completed</p></div><div class="progress-journey-count">${String(complete).padStart(2,'0')}<small> / ${String(total).padStart(2,'0')}</small></div></header><div class="progress-journey-track">${journey.map((item,index)=>`<article class="progress-milestone ${item.complete?'is-complete':''} ${next===item?'is-next':''}"><div class="progress-milestone-pin"><i>${item.complete?'✓':String(index+1).padStart(2,'0')}</i><b></b></div><div class="progress-milestone-copy"><span>${item.complete?'COMPLETED':next===item?'UP NEXT':'MILESTONE '+String(index+1).padStart(2,'0')}</span><strong>${escapeHTML(item.stage)}</strong><small>${item.complete?'Saved activity recorded':next===item?'Your next opportunity to make progress':'Waiting for this step'}</small></div></article>`).join('')}</div></section>${p.latest_ats==null?'':`<section class="progress-ats-card"><div><span>RESUME SIGNAL</span><h3>Latest ATS estimate</h3><p>A heuristic score from your latest resume analysis.</p><a class="button button-primary progress-ats-action" href="resume-analyzer.html">Open resume analysis →</a></div><div class="progress-ats-score"><b>${escapeHTML(p.latest_ats)}</b><span>/ 100</span><i><b style="width:${Math.max(0,Math.min(100,Number(p.latest_ats)||0))}%"></b></i></div></section>`}`}catch(err){root.innerHTML=msg(err.message,true)}}
init();
